import{_t as e,it as t,n,rt as r}from"./chunks/framework.BM2esBXZ.js";var i=JSON.parse(`{"title":"包总览","description":"","frontmatter":{},"headers":[],"relativePath":"packages/index.md","filePath":"packages/index.md","lastUpdated":1794051466000}`),a={name:`packages/index.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="包总览" tabindex="-1">包总览 <a class="header-anchor" href="#包总览" aria-label="Permalink to “包总览”">​</a></h1><p>XiHan Framework 由一组可以独立引用的 NuGet 包组成，按环层组织。本册是参考手册，每个包一页，列出它提供的能力、配置节、主要类型、限制与错误码；要完成某件事时先读<a href="/startup/features">开发指南</a>。</p><div class="tip custom-block"><p class="custom-block-title">先看指南还是先看这里</p><table tabindex="0"><thead><tr><th>问题</th><th>去处</th></tr></thead><tbody><tr><td>要做某件事：装配特性、写操作、接数据库、做授权、发消息</td><td><a href="/startup/features">开发指南</a></td></tr><tr><td>某个包有什么：能力 ID、配置键、主要类型、AOT 与限制</td><td>本册</td></tr></tbody></table></div><p>当前是预览版，全部包共享一条版本线，取得方式见<a href="/getting-started/installation">快速上手</a>。</p><h2 id="命名规则" tabindex="-1">命名规则 <a class="header-anchor" href="#命名规则" aria-label="Permalink to “命名规则”">​</a></h2><p>包 ID 由术语表与文法推出：<code>XiHan.Framework.&lt;领域&gt;[.&lt;角色&gt;]</code>。</p><table tabindex="0"><thead><tr><th>后缀</th><th>角色</th><th>示例</th></tr></thead><tbody><tr><td><code>.Abstractions</code></td><td>抽象包：接口、契约、阶段中间件，零第三方依赖</td><td><code>Caching.Abstractions</code></td></tr><tr><td>机制名</td><td>默认实现：零外部设施、容量有界，清单角色为 <code>default</code></td><td><code>Caching.InMemory</code>、<code>ObjectStorage.FileSystem</code></td></tr><tr><td><code>.Database</code></td><td>经持久化子系统的仓储读写的 Provider，数据库由应用选中的持久化 Provider 决定</td><td><code>Security.Database</code></td></tr><tr><td>技术名</td><td>接外部设施的 Provider</td><td><code>Caching.Redis</code>、<code>Persistence.EntityFrameworkCore</code></td></tr><tr><td><code>.Conformance</code></td><td>一致性套件：实现必须通过的 xUnit 测试</td><td><code>Caching.Conformance</code></td></tr><tr><td><code>.Generators</code> / <code>.Analyzers</code></td><td>源生成器与分析器，开发期依赖</td><td><code>Kernel.Generators</code></td></tr></tbody></table><p>默认是清单里的 <code>role</code>，不是包名：没有显式 Provider 时默认实现被选中，加入 Provider 后自动让位。</p><h2 id="怎样选包" tabindex="-1">怎样选包 <a class="header-anchor" href="#怎样选包" aria-label="Permalink to “怎样选包”">​</a></h2><ol><li>先选组合包：<code>Profiles.Minimal</code>（内核、ASP.NET Core 宿主、内存本地化）、<code>Profiles.Standard</code>（再加持久化、缓存、多租户、安全、消息的内存默认实现）、<code>Profiles.Full</code>（再加对象存储、调度、审计、工作流、AI 工具目录、OpenTelemetry、运行信息与四种协议适配器）。</li><li>按对外暴露的方式加协议适配器：<code>Protocols.Http</code>、<code>Protocols.Grpc</code>、<code>Protocols.Mcp</code>、<code>Protocols.CloudEvents</code>，或换成命令行宿主 <code>Hosting.CommandLine</code>。</li><li>按生产环境的外部设施加 Provider：<code>Persistence.EntityFrameworkCore</code> / <code>Persistence.SqlSugar</code>、<code>Caching.Redis</code>、<code>Messaging.RabbitMQ</code> / <code>Messaging.Kafka</code>、<code>Security.Jwt</code> / <code>Security.OpenIdConnect</code>、<code>ObjectStorage.S3</code> 等，每个都要 <code>UseFeature</code> 加入。</li><li>开发期依赖：<code>Kernel.Generators</code>（操作契约）与 <code>Persistence.Generators</code>（仓储登记）。</li></ol><h2 id="ring-0–1-原语与内核" tabindex="-1">Ring 0–1 原语与内核 <a class="header-anchor" href="#ring-0–1-原语与内核" aria-label="Permalink to “Ring 0–1 原语与内核”">​</a></h2><table tabindex="0"><thead><tr><th>包</th><th>说明</th></tr></thead><tbody><tr><td><a href="./primitives">Primitives</a></td><td>原语与契约：<code>Result</code>、<code>Error</code>、<code>Maybe</code>、<code>InvocationContext</code>、清单模型、管道阶段、生命周期状态、消息键；只增不改</td></tr><tr><td><a href="./kernel">Kernel</a></td><td>微内核：应用构建、能力图谱、管道与内置中间件、操作契约与调用器、安全原语、健康、插件抽象</td></tr></tbody></table><h2 id="ring-2-领域与抽象" tabindex="-1">Ring 2 领域与抽象 <a class="header-anchor" href="#ring-2-领域与抽象" aria-label="Permalink to “Ring 2 领域与抽象”">​</a></h2><table tabindex="0"><thead><tr><th>包</th><th>说明</th></tr></thead><tbody><tr><td><a href="./domain">Domain</a></td><td>实体协议接口、值对象、领域事件缓冲、规约；纯契约</td></tr><tr><td><a href="./persistence-abstractions">Persistence.Abstractions</a></td><td>仓储、查询、工作单元与 Transaction 阶段、标识生成、领域事件派发</td></tr><tr><td><a href="./caching-abstractions">Caching.Abstractions</a></td><td>字节存储、类型化缓存、序列化器、分布式锁、Idempotency 阶段、<code>IDistributedCache</code> 适配、键管理</td></tr><tr><td><a href="./multitenancy-abstractions">MultiTenancy.Abstractions</a></td><td>租户信息与存储、租户解析器与 Tenant 阶段、租户分片</td></tr><tr><td><a href="./security-abstractions">Security.Abstractions</a></td><td>凭据与认证处理器、权限与策略、RBAC 授予、Authenticate / Authorize 阶段、条件引擎、IP 归属地契约</td></tr><tr><td><a href="./messaging-abstractions">Messaging.Abstractions</a></td><td>CloudEvents 信封、发布与订阅、经管道的派发、发件箱、领域事件映射</td></tr><tr><td><a href="./localization-abstractions">Localization.Abstractions</a></td><td>区域、消息目录、显式区域的本地化接口</td></tr><tr><td><a href="./objectstorage-abstractions">ObjectStorage.Abstractions</a></td><td>对象存储契约：批量写入与删除、按前缀列举、范围读取、分片上传、预签名</td></tr><tr><td><a href="./scheduling-abstractions">Scheduling.Abstractions</a></td><td>作业、触发器、计划、调度引擎与作业存储契约、领导选举</td></tr><tr><td><a href="./configuration-abstractions">Configuration.Abstractions</a></td><td>远程配置与密钥契约、接入 <code>IConfigurationBuilder</code> 的配置源</td></tr><tr><td><a href="./auditing-abstractions">Auditing.Abstractions</a></td><td>Observe 阶段审计中间件、审计扩展与查询契约</td></tr><tr><td><a href="./observability-abstractions">Observability.Abstractions</a></td><td>进程与主机运行信息的契约</td></tr><tr><td><a href="./workflow-abstractions">Workflow.Abstractions</a></td><td>工作流定义模型、目录、引擎、内置活动、用户任务、存储契约</td></tr><tr><td><a href="./ai-abstractions">AI.Abstractions</a></td><td>基于 <code>Microsoft.Extensions.AI</code> 的 Provider 目录、<code>IAIChat</code>、护栏、工具目录、知识库</td></tr></tbody></table><h2 id="ring-3-默认实现与-provider" tabindex="-1">Ring 3 默认实现与 Provider <a class="header-anchor" href="#ring-3-默认实现与-provider" aria-label="Permalink to “Ring 3 默认实现与 Provider”">​</a></h2><table tabindex="0"><thead><tr><th>领域</th><th>默认实现</th><th>Provider</th></tr></thead><tbody><tr><td>持久化</td><td><a href="./persistence-inmemory">Persistence.InMemory</a></td><td><a href="./persistence-entityframeworkcore">EntityFrameworkCore</a>、<a href="./persistence-sqlsugar">SqlSugar</a></td></tr><tr><td>缓存</td><td><a href="./caching-inmemory">Caching.InMemory</a></td><td><a href="./caching-redis">Redis</a>、<a href="./caching-hybrid">Hybrid</a>、<a href="./caching-remote">Remote</a>（Experimental）</td></tr><tr><td>多租户</td><td><a href="./multitenancy-inmemory">MultiTenancy.InMemory</a></td><td><a href="./multitenancy-database">Database</a></td></tr><tr><td>安全</td><td><a href="./security-inmemory">Security.InMemory</a></td><td><a href="./security-database">Database</a>、<a href="./security-jwt">Jwt</a>、<a href="./security-openidconnect">OpenIdConnect</a>、<a href="./security-ip2region">Ip2Region</a></td></tr><tr><td>消息</td><td><a href="./messaging-inmemory">Messaging.InMemory</a></td><td><a href="./messaging-rabbitmq">RabbitMQ</a>、<a href="./messaging-kafka">Kafka</a></td></tr><tr><td>本地化</td><td><a href="./localization-inmemory">Localization.InMemory</a></td><td><a href="./localization-database">Database</a></td></tr><tr><td>对象存储</td><td><a href="./objectstorage-filesystem">ObjectStorage.FileSystem</a></td><td><a href="./objectstorage-s3">S3</a></td></tr><tr><td>调度</td><td><a href="./scheduling-inmemory">Scheduling.InMemory</a></td><td><a href="./scheduling-database">Database</a>、<a href="./scheduling-kubernetes">Kubernetes</a></td></tr><tr><td>配置</td><td>.NET 原生的文件与环境变量，无包</td><td><a href="./configuration-nacos">Nacos</a></td></tr><tr><td>审计</td><td><a href="./auditing-inmemory">Auditing.InMemory</a></td><td><a href="./auditing-database">Database</a></td></tr><tr><td>可观测性</td><td><a href="./observability-host">Observability.Host</a>（运行信息）</td><td><a href="./observability-opentelemetry">OpenTelemetry</a>（导出）</td></tr><tr><td>工作流</td><td><a href="./workflow-inmemory">Workflow.InMemory</a></td><td><a href="./workflow-database">Database</a></td></tr><tr><td>AI</td><td>工具目录由 <code>AI.Abstractions</code> 的 <code>AIToolsFeature</code> 提供</td><td><a href="./ai-openai">OpenAI</a>、<a href="./ai-vectordata">VectorData</a></td></tr></tbody></table><p>插件协议的 .NET 类型 <a href="./plugins-protocol">Plugins.Protocol</a> 也在 Ring 3，由各隔离级别的插件宿主共用。</p><h2 id="ring-4-宿主" tabindex="-1">Ring 4 宿主 <a class="header-anchor" href="#ring-4-宿主" aria-label="Permalink to “Ring 4 宿主”">​</a></h2><table tabindex="0"><thead><tr><th>包</th><th>说明</th></tr></thead><tbody><tr><td><a href="./hosting-aspnetcore">Hosting.AspNetCore</a></td><td>HTTP 请求桥接进管道、<code>Accept-Language</code> 协商、探针端点、本地化的 Problem Details、<code>XiHan</code> 认证方案</td></tr><tr><td><a href="./hosting-commandline">Hosting.CommandLine</a></td><td>命令行宿主：<code>help</code> / <code>graph</code> / <code>pipeline</code> / <code>operations</code> / <code>invoke</code>，按错误 KIND 的退出码</td></tr></tbody></table><h2 id="ring-5-协议与插件" tabindex="-1">Ring 5 协议与插件 <a class="header-anchor" href="#ring-5-协议与插件" aria-label="Permalink to “Ring 5 协议与插件”">​</a></h2><table tabindex="0"><thead><tr><th>包</th><th>说明</th></tr></thead><tbody><tr><td><a href="./protocols-http">Protocols.Http</a></td><td>操作 ID 推导路由、载荷绑定、OpenAPI 3.1</td></tr><tr><td><a href="./protocols-grpc">Protocols.Grpc</a></td><td>操作成为一元方法，protobuf 由 JSON Schema 推出，发布 <code>/operations.proto</code></td></tr><tr><td><a href="./protocols-mcp">Protocols.Mcp</a></td><td>操作成为 MCP tool，Streamable HTTP 与 stdio 传输</td></tr><tr><td><a href="./protocols-cloudevents">Protocols.CloudEvents</a></td><td>CloudEvents 1.0 HTTP 绑定：入站 <code>/events</code> 与出站 Webhook</td></tr><tr><td><a href="./plugins-inprocess">Plugins.InProcess</a></td><td>可收集 <code>AssemblyLoadContext</code> 的进程内插件宿主</td></tr><tr><td><a href="./plugins-outofprocess">Plugins.OutOfProcess</a></td><td>按 <code>xihan.plugin.v1</code> 启动与监视子进程的插件宿主，插件可用任意语言编写</td></tr><tr><td><a href="./plugins-wasm">Plugins.Wasm</a></td><td>wasmtime 沙箱里的 Wasm 插件宿主（Experimental）</td></tr></tbody></table><h2 id="ring-6-组合包" tabindex="-1">Ring 6 组合包 <a class="header-anchor" href="#ring-6-组合包" aria-label="Permalink to “Ring 6 组合包”">​</a></h2><table tabindex="0"><thead><tr><th>包</th><th>内容</th></tr></thead><tbody><tr><td><a href="./profiles-minimal">Profiles.Minimal</a></td><td>Primitives + Kernel + Hosting.AspNetCore + Localization.InMemory，<code>UseMinimalProfile()</code></td></tr><tr><td><a href="./profiles-standard">Profiles.Standard</a></td><td>Minimal + Domain + 五个子系统的抽象与内存默认实现，<code>UseStandardProfile()</code></td></tr><tr><td><a href="./profiles-full">Profiles.Full</a></td><td>Standard + 对象存储、调度、审计、工作流、AI 工具、OpenTelemetry、运行信息与四种协议适配器，<code>UseFullProfile()</code></td></tr></tbody></table><h2 id="工具链" tabindex="-1">工具链 <a class="header-anchor" href="#工具链" aria-label="Permalink to “工具链”">​</a></h2><table tabindex="0"><thead><tr><th>包</th><th>说明</th></tr></thead><tbody><tr><td><a href="./kernel-generators">Kernel.Generators</a></td><td>源生成器：<code>[Operation]</code> → 登记代码与请求 / 响应 JSON Schema（XHG001–XHG006）</td></tr><tr><td><a href="./kernel-analyzers">Kernel.Analyzers</a></td><td>Roslyn 分析器：<code>ApiLevel</code>、命名、Internal 引用、零反射</td></tr><tr><td><a href="./persistence-generators">Persistence.Generators</a></td><td>源生成器：实体 → 仓储登记、EF Core 实体登记、软删除与租户过滤规约</td></tr><tr><td><a href="./cli">Cli</a></td><td>命令行工具 <code>xihan</code>：<code>pack</code> 生成部署产物，转发 <code>graph</code> / <code>pipeline</code> / <code>operations</code> / <code>invoke</code></td></tr><tr><td><a href="./testing">Testing</a></td><td>测试宿主、特性桩、清单与上下文构造</td></tr><tr><td><a href="./conformance">Conformance</a></td><td>各领域的一致性套件与插件协议黑盒套件</td></tr></tbody></table><p>工具链包可以引用任何环；源生成器与分析器只在编译期运行，不进入应用的运行时依赖。</p>`,26)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};